import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';

const sourceUrl = new URL('../entry/src/main/resources/rawfile/almanac.json', import.meta.url);
const targetUrl = new URL('../entry/src/main/ets/model/AlmanacData.ts', import.meta.url);
const sourceText = await readFile(sourceUrl, 'utf8');
const database = JSON.parse(sourceText);
const digest = createHash('sha256').update(sourceText).digest('hex');
const generated = [
  '// Generated by scripts/generate-almanac-data.mjs. Do not edit manually.',
  "import { AlmanacDatabase } from './AlmanacEngine';",
  '',
  `export const ALMANAC_DATA_SHA256: string = '${digest}';`,
  `export const ALMANAC_DATABASE: AlmanacDatabase = ${JSON.stringify(database, null, 2)};`,
  ''
].join('\n');

await writeFile(targetUrl, generated, 'utf8');
console.log(`Generated ${targetUrl.pathname}`);
